DROP TABLE IF EXISTS `dokumens`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `dokumens` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `tps_id` bigint unsigned DEFAULT NULL,
  `kecamatan_id` bigint unsigned DEFAULT NULL,
  `uploaded_by` bigint unsigned NOT NULL,
  `jenis` enum('PPWP','GUBERNUR','BUPATI','DPD','DPR_RI','DPRD_PROV','DPRD_KAB') COLLATE utf8mb4_unicode_ci NOT NULL,
  `level` enum('tps','kecamatan') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'tps',
  `status` enum('menunggu_verifikasi','terverifikasi','ditolak') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'menunggu_verifikasi',
  `komentar` text COLLATE utf8mb4_unicode_ci,
  `is_archived` tinyint(1) NOT NULL DEFAULT '0',
