  UNIQUE KEY `dokumens_tps_id_jenis_unique` (`tps_id`,`jenis`),
  KEY `dokumens_kecamatan_id_foreign` (`kecamatan_id`),
  KEY `dokumens_uploaded_by_foreign` (`uploaded_by`),
  KEY `dokumens_verified_by_foreign` (`verified_by`),
  CONSTRAINT `dokumens_kecamatan_id_foreign` FOREIGN KEY (`kecamatan_id`) REFERENCES `kecamatans` (`id`) ON DELETE CASCADE,
  CONSTRAINT `dokumens_tps_id_foreign` FOREIGN KEY (`tps_id`) REFERENCES `tps` (`id`) ON DELETE CASCADE,
  CONSTRAINT `dokumens_uploaded_by_foreign` FOREIGN KEY (`uploaded_by`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `dokumens_verified_by_foreign` FOREIGN KEY (`verified_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
